import struct
import zlib

# Constants
KEY = '470FC614'


def task_func(hex_string=KEY):
    if not isinstance(hex_string, str):
        raise TypeError("hex_string must be a string")

    cleaned = hex_string.strip()
    if cleaned.lower().startswith("0x"):
        cleaned = cleaned[2:]

    if not cleaned:
        raise ValueError("hex_string is empty")

    if len(cleaned) > 8:
        raise ValueError("hex_string must fit in 32 bits (at most 8 hex digits)")

    try:
        bits = int(cleaned, 16)
    except ValueError as exc:
        raise ValueError("hex_string must contain only hexadecimal digits") from exc

    if not 0 <= bits <= 0xFFFFFFFF:
        raise ValueError("hex_string must fit in 32 bits")

    float_value = struct.unpack("!f", struct.pack("!I", bits))[0]
    binary32_bytes = struct.pack("!f", float_value)
    compressed_bytes = zlib.compress(binary32_bytes)

    return {"bytes": compressed_bytes}
